import 'dart:convert'; import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'models/user.dart'; import 'screens/entry.dart'; import 'screens/home.dart'; import 'screens/admin_home.dart'; import 'services/update_service.dart'; import 'theme.dart';
void main()=>runApp(const CampusMate());
class CampusMate extends StatelessWidget{const CampusMate({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'CampusMate',theme:AppTheme.light(),home:const Gate());}
class Gate extends StatefulWidget{const Gate({super.key});@override State<Gate> createState()=>_GateState();}
class _GateState extends State<Gate>{bool loading=true;User? user;@override void initState(){super.initState();boot();}Future<void> boot()async{final p=await SharedPreferences.getInstance();final s=p.getString('user');if(s!=null)try{user=User.fromJson(jsonDecode(s));}catch(_){await p.clear();}if(!mounted)return;setState(()=>loading=false);if(user!=null)WidgetsBinding.instance.addPostFrameCallback((_)=>UpdateService.check(context));}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return user==null?const Entry():(user!.role=='admin'?AdminHome(user:user!):Home(user:user!));}}
